    "cal.current": "Current fit",
    "cal.off": "Off",
    "cal.average": "Average",
    "cal.adaptive": "Adaptive",
    "cal.desc.off": "No calibration — shows the raw pharmacokinetic model.",
    "cal.desc.average": "Amplitude-only correction: one personal scale fit by log-space least squares (geometric mean of measured ÷ predicted). Adjusts overall level, not curve shape.",
    "cal.desc.adaptive": "Joint amplitude + clearance fit: re-simulates your PK across a grid of elimination-rate multipliers and selects the scale and half-life that minimize the log-residuals. Needs 3+ well-spaced labs to shift clearance; otherwise falls back to amplitude only.",
    "cal.recommended": "Recommended",
    "cal.off.pro.1": "Fully transparent — never skewed by an odd lab value",
    "cal.off.con.1": "No personalization to your measured levels",
    "cal.average.pro.1": "Robust single scale from all labs; insensitive to outliers",
    "cal.average.pro.2": "Works from a single lab",
    "cal.average.con.1": "Shifts the whole curve up/down — can't fix shape or half-life",
    "cal.adaptive.pro.1": "Learns amplitude and clearance together — corrects curve shape",
    "cal.adaptive.pro.2": "Lowest fit error; bounded so it can't run away",
    "cal.adaptive.con.1": "Needs 3+ well-spaced labs to move half-life",
    "cal.ekf": "EKF",
    "cal.ou_kalman": "OU-Kalman",
    "cal.mipd": "Hybrid-MIPD",
    "cal.desc.ekf": "Extended Kalman Filter. Walks your labs in time order, keeping a running estimate of personal amplitude and clearance with its uncertainty. Permanent memory — every lab leaves a mark.",
    "cal.desc.ou_kalman": "Ornstein–Uhlenbeck Kalman smoother. Treats the correction as a level that drifts and reverts toward the model — each lab's pull fades over about two weeks. Tracks change over time rather than one fixed scale.",
    "cal.desc.mipd": "Model-informed precision dosing. MAP fit of amplitude and clearance under a population prior with a robust (Student-t) likelihood: leans on the population when labs are sparse and shrugs off a lone outlier.",
    "cal.ekf.pro.1": "Learns amplitude and clearance, updating with every lab",
    "cal.ekf.pro.2": "Tracks its own uncertainty; bounded so it can't run away",
    "cal.ekf.con.1": "Permanent memory — an old lab keeps pulling the estimate",
    "cal.ou_kalman.pro.1": "Follows a level that drifts over time, not one fixed scale",
    "cal.ou_kalman.pro.2": "Recent labs weigh more; old ones fade on their own",
    "cal.ou_kalman.con.1": "Corrects level only — won't reshape the curve or half-life",
    "cal.mipd.pro.1": "Robust to outliers; leans on the population when data is thin",
    "cal.mipd.pro.2": "Learns amplitude and clearance; works from a single lab",
    "cal.mipd.con.1": "Needs 3+ well-spaced labs before it moves half-life",
    "cal.history": "Applied to history",
    "cal.forward": "Forward",
    "cal.retrospective": "Retrospective",
    "cal.desc.forward": "Causal — each point uses only the labs available by then, so past estimates never change when you add a new lab.",
    "cal.desc.retrospective": "Smoothed — all labs re-estimate the whole history. More accurate in hindsight; a new lab can revise older estimates.",
    "cal.source": "Calibration models mirror those on hrt.transmtf.com.",
